  return Attributes;
}

import { consultarCooperativaService } from './service.mjs';

export async function handler(event) {
  const cooperativaId = Number(event.pathParameters.cooperativaId);
  const minimo = Number(event.queryStringParameters?.minimo ?? 0);
  const resultado = await consultarCooperativaService(cooperativaId, minimo);
  return { statusCode: 200, body: JSON.stringify(resultado) };
}

import { buscarCooperativaRepository, consultarCooperativaRepository } from './repository.mjs';

export async function consultarCooperativaService(cooperativaId, minimo) {
  const cooperativa = await buscarCooperativaRepository(cooperativaId);
  if (!cooperativa) throw new Error('Cooperativa no encontrado');
  const lotes = await consultarCooperativaRepository(cooperativaId, minimo);
  return { cooperativa, lotes };
}

import { EntityRepository } from 'dynamodb-toolbox/entity/actions/repository';
import { MODELO_LOTE, MODELO_COOPERATIVA } from '../../models/cooperativa-lote.model.mjs';

export async function buscarCooperativaRepository(cooperativaId) {
  const { Item } = await MODELO_COOPERATIVA.build(EntityRepository).get(
    { cooperativaId },
    { consistent: true }
  );
  return Item ?? null;
}

export async function consultarCooperativaRepository(cooperativaId, minimo) {
  const { Items = [] } = await MODELO_LOTE.build(EntityRepository).query(
    { index: 'PorCooperativa', partition: cooperativaId },
    { filters: { Lote: { attr: 'kilos', gte: minimo } } }
  );
  return Items;
}
